for d in DATA:
    n=wc(d["body"])
    if not 2000<=n<=3000:
        print(f'ERROR - {d["filename"]}: {n} words'); raise SystemExit(1)
    if not (ART/d["filename"]).exists():
        print("ERROR - file not found:",d["filename"]); raise SystemExit(1)
for d in DATA:
    p=ART/d["filename"]; t=p.read_text(encoding="utf-8",errors="replace")
    b=BACK/d["filename"]
    if not b.exists(): shutil.copy2(p,b)
    t=re.sub(r'<html\s+lang=["\']es["\']','<html lang="en"',t,flags=re.I)
    t=re.sub(r'(<h1[^>]*>).*?(</h1>)',lambda m:m.group(1)+d["title"]+m.group(2),t,count=1,flags=re.I|re.S)
    t=re.sub(r'(<title[^>]*>).*?(</title>)',lambda m:m.group(1)+d["title"]+" | Home & Garden"+m.group(2),t,count=1,flags=re.I|re.S)
    t=re.sub(r'(<meta[^>]+name=["\']description["\'][^>]+content=["\'])[^"\']*(["\'])',lambda m:m.group(1)+d["desc"]+m.group(2),t,count=1,flags=re.I|re.S)
    t=re.sub(r'(<p[^>]+class=["\'][^"\']*article-intro[^"\']*["\'][^>]*>).*?(</p>)',lambda m:m.group(1)+d["intro"]+m.group(2),t,count=1,flags=re.I|re.S)
    t=re.sub(r'(<span[^>]+class=["\'][^"\']*article-category[^"\']*["\'][^>]*>).*?(</span>)',lambda m:m.group(1)+d["category"]+m.group(2),t,count=1,flags=re.I|re.S)
    pat=r'(<article\b[^>]*class=["\'][^"\']*article-content-full[^"\']*["\'][^>]*>).*?(</article>)'
    t,n=re.subn(pat,lambda m:m.group(1)+"\n"+d["body"]+"\n"+m.group(2),t,count=1,flags=re.I|re.S)
    if n!=1: print("ERROR - article-content-full not found:",d["filename"]); raise SystemExit(1)
    for a,bv in {"Casa & Jardín":"Home & Garden","Publicado:":"Published:","Actualizado:":"Updated:","Inicio":"Home","Categorías":"Categories","Sobre nosotros":"About Us","Contacto":"Contact","Compartir":"Share","Artículos recientes":"Recent Articles","También te puede interesar":"You May Also Like","HOGAR":"HOME","JARDINERÍA":"GARDENING","DECORACIÓN":"HOME DECOR","Equipo Editorial de Casa & Jardín":"Home & Garden Editorial Team"}.items(): t=t.replace(a,bv)
